def shapes8(G, bg):
    from collections import deque
    H,W = G.shape; seen = np.zeros_like(G,bool); res=[]
    for r in range(H):
        for c in range(W):
            if G[r,c]!=bg and not seen[r,c]:
                col=G[r,c]; q=deque([(r,c)]); seen[r,c]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            if dy==0 and dx==0: continue
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and not seen[ny,nx] and G[ny,nx]==col:
                                seen[ny,nx]=True; q.append((ny,nx))
                res.append((col, tuple(sorted(cells))))
    return res

