def pat(cells):
    ys=[y for y,x in cells]; xs=[x for y,x in cells]
    h=max(ys)-min(ys)+1; w=max(xs)-min(xs)+1
    g=[[0]*w for _ in range(h)]
    for y,x in cells: g[y-min(ys)][x-min(xs)]=1
    return tuple(tuple(r) for r in g)

